		775: [{
			type: "FUNC",
			attachedEntity: true,
			func: function(Params) {
				const entity = Params.Init.ownerEntity;
				const duration = 500;
				const count = 8;
				const delay = duration / count;
				for (let i = 0; i < count; i++) {
					var delta = 1;
					Events.setTimeout(function() {
						entity.direction = Math.floor(entity.direction + delta) % 8;
					}, delay * i);
				}
			}
		}],
