	/**
	* Search for NPCs or MOBs in the navigation tables
	*
	* @param {string} query - The search query
	* @param {string} type - The type of search (ALL, NPC, MOB)
	* @returns {Array} Array of search results
	*/
	DB.searchNavigation = function searchNavigation(query, type) {
		if (!query || query.length < 2) return [];
		query = query.toLowerCase();
		const results = [];
		if (type === "ALL" || type === "NPC") for (let i = 0; i < NaviNpcTable.length; i++) {
			const npc = NaviNpcTable[i];
			const mapName = npc[0];
			const npcId = npc[1];
			const npcName = npc[4] || "";
			if (!npcName) continue;
			if (npcName.toLowerCase().indexOf(query) !== -1) results.push({
				type: "NPC",
				id: npcId,
				name: npcName,
				mapName,
				x: npc[6],
				y: npc[7]
			});
		}
		if (type === "ALL" || type === "MOB") for (let i = 0; i < NaviMobTable.length; i++) {
			const mob = NaviMobTable[i];
			const mapName = mob[0];
			const mobId = mob[3];
			const mobName = mob[4] || "";
			if (!mobName) continue;
			if (mobName.toLowerCase().indexOf(query) !== -1) results.push({
				type: "MOB",
				id: mobId,
				name: mobName,
				mapName,
				x: null,
				y: null
			});
		}
		results.sort(function(a, b) {
			return a.name.localeCompare(b.name);
		});
		return results.slice(0, 50);
	};
