		if (pkt.rankType === 0) message += DB.getMessage(2386);
		else if (pkt.rankType === 1) message += DB.getMessage(2387);
		else if (pkt.rankType === 2) message += DB.getMessage(2388);
		else if (pkt.rankType === 3) message += DB.getMessage(2389);
