/**
* Entity will be hit, handle getting hit and after actions
*
* @param pkt - packet PACKET.ZC.NOTIFY_ACT or PACKET.ZC.NOTIFY_SKILL
* @param dstEntity - Reveiver entity
*/
function onEntityWillBeHitSub(pkt, dstEntity) {
	if ((pkt.damage > 0 || pkt.leftDamage > 0) && pkt.action !== 4 && pkt.action !== 9 && pkt.action !== 11) {
		const count = pkt.count || 1;
		function impendingAttack() {
			if (dstEntity.action !== dstEntity.ACTION.DIE) dstEntity.setAction({
				action: dstEntity.ACTION.HURT,
				frame: 0,
				repeat: false,
				play: true,
				next: {
					action: dstEntity.ACTION.READYFIGHT,
					delay: pkt.attackedMT + 0,
					frame: 0,
					repeat: true,
					play: true
				}
			});
		}
		function resumeWalk() {
			if (dstEntity.action !== dstEntity.ACTION.DIE && EntityManager.getFocusEntity() && dstEntity.walk.index < dstEntity.walk.total) dstEntity.setAction({
				action: dstEntity.ACTION.WALK,
				frame: 0,
				repeat: false,
				play: true
			});
		}
		for (let i = 0; i < count; i++) {
			if (pkt.damage) Events.setTimeout(impendingAttack, pkt.attackMT + C_MULTIHIT_DELAY * i);
			if (pkt.leftDamage) Events.setTimeout(impendingAttack, pkt.attackMT + C_MULTIHIT_DELAY * 1.75 * i);
		}
		Events.setTimeout(resumeWalk, pkt.attackMT + C_MULTIHIT_DELAY * (pkt.leftDamage ? 1.75 : 1) * (count - 1) + pkt.attackedMT);
	}
}
